/**
 * DSH-compatible YAML emission and parsing for bundle patches. `!!js`
 * expression scalars use the Loader's vendored convention, so an emitted file
 * round-trips through DSH without a second dialect.
 * @module @eedsh/bundle/yaml
 */

import * as yaml from 'js-yaml'
import type { BundlePatch, PatchEntry } from './patch'
import { BundlePatchError, validateBundlePatch } from './validate'

/** The header emitted before a generated plugin `cordis.patch.yml`. */
export const BUNDLE_PATCH_HEADER =
  '# Generated by @eedsh/bundle from the TypeScript bundle definition. Do not edit by hand; edit the definition and regenerate.\n'

/** One serialized Loader JavaScript expression. */
interface JsExpressionData {
  __jsExpr: string
}

/** Whether a value is a serialized Loader JavaScript expression. */
function isJsExpression(value: unknown): value is JsExpressionData {
  return value instanceof Object && '__jsExpr' in value
}

const JsExpression = new yaml.Type('tag:yaml.org,2002:js', {
  kind: 'scalar',
  resolve: (data) => typeof data === 'string',
  construct: (data) => ({ __jsExpr: data as string }),
  predicate: (data) => isJsExpression(data),
  represent: (data) => (data as JsExpressionData).__jsExpr,
})

/** The entry-list YAML dialect: JSON values plus `!!js` expression scalars. */
const entryListSchema: yaml.Schema = yaml.JSON_SCHEMA.extend(JsExpression)

/**
 * Convert expression nodes into the shape DSH's YAML schema represents,
 * leaving every other value untouched.
 * @param value - plain patch data.
 * @returns the same data with `{ "$eedsh": { "expr": ... } }` nodes replaced.
 */
function toExpressionData(value: unknown): unknown {
  if (Array.isArray(value)) return value.map((item) => toExpressionData(item))
  if (value !== null && typeof value === 'object') {
    const record = value as Record<string, unknown>
    if ('$eedsh' in record) {
      const node = record.$eedsh
      if (
        Object.keys(record).length === 1 &&
        node !== null &&
        typeof node === 'object' &&
        typeof (node as { expr?: unknown }).expr === 'string'
      ) {
        return { __jsExpr: (node as { expr: string }).expr }
      }
      throw new Error('cannot emit a malformed expression node')
    }
    const out: Record<string, unknown> = {}
    for (const [key, item] of Object.entries(record)) out[key] = toExpressionData(item)
    return out
  }
  return value
}

/**
 * Emit one ordered patch list as YAML, without a generated-file header. The
 * eedsh CLI uses this for generated profile layers.
 * @param patches - the bundle patch.
 * @returns YAML text ending with one newline.
 */
export function emitPatchesYaml(patches: readonly PatchEntry[]): string {
  validateBundlePatch(patches)
  const text = yaml.dump(toExpressionData(patches), { schema: entryListSchema, noRefs: true })
  return text.endsWith('\n') ? text : `${text}\n`
}

/**
 * Emit a generated plugin patch file: a short generated-file header followed
 * by the DSH patch list.
 * @param patch - the bundle patch.
 * @returns YAML text ending with one newline.
 */
export function emitBundlePatch(patch: BundlePatch): string {
  return `${BUNDLE_PATCH_HEADER}${emitPatchesYaml(patch)}`
}

/**
 * Parse a DSH patch list. This is intentionally permissive about patch
 * semantics: composition and unmatched targets belong to DSH, and the CLI
 * uses this to read generated profile layers.
 * @param text - YAML text.
 * @returns the top-level patch array.
 * @throws {BundlePatchError} when the text is not a top-level array.
 */
export function loadPatchesYaml(text: string): PatchEntry[] {
  const parsed = yaml.load(text, { schema: entryListSchema })
  if (!Array.isArray(parsed)) {
    throw new BundlePatchError([
      { path: [], message: 'expected a top-level YAML array of patch entries' },
    ])
  }
  return parsed as PatchEntry[]
}
